        }
        $scriptProperties['parents'] = !empty($parents) ? implode(',', $parents) : '+0';
        $scriptProperties['depth'] = 0;
    }
    $scriptProperties['includeParents'] = 1;
    $scriptProperties['displayStart'] = 0;
} else {
