/** @var array $scriptProperties */
/** @var msFavorites $msFavorites */
if (!$msFavorites = $modx->getService('msfavorites.msFavorites', '', MODX_CORE_PATH . 'components/msfavorites/model/')) {
    return 'Could not load msFavorites class!';
}
/** @var pdoFetch $pdoFetch */
if (!$modx->loadClass('pdofetch', MODX_CORE_PATH . 'components/pdotools/model/pdotools/', false, true)) {
    return false;
}

if (!empty($returnIds)) {
    $return = 'ids';
}
if ($return === 'ids') {
    $returnIds = 1;
}

if (!isset($list) or $list == '') {
    $list = 'default';
}
if (!isset($type) or $type == '') {
    $type = 'resource';
}


$request = xss_esc($_GET);
$service = $modx->getOption('service', $request);
$share = $service === 'msfavorites';
if ($share) {
    $type = $modx->getOption('type', $request,'resource', true);
    $uid = $modx->getOption('uid', $request);

    $keys = $modx->getOption('keys', $request);
    $keys = array_map('trim', explode(',', $keys));
    $keys = array_filter($keys);

    $list = $modx->getOption('list', $request,'default', true);

    if (empty($keys)) {
        $lid = 0;
        if ($lo = $modx->getObject('msfFavoriteList', ['list' => $list])) {
            $lid = $lo->get('id');
        }

        $c = $modx->newQuery('msfFavoriteObject');
        $c->leftJoin('msfFavoriteKey', 'FavoriteKey');
        $c->where(['lid' => $lid, 'uid' => $uid]);
        $c->limit(0);
        $c->select('key');
        if ($c->prepare() and $c->stmt->execute()) {
            while ($row = $c->stmt->fetch(PDO::FETCH_ASSOC)) {
                if (!empty($row['key'])) {
                    $keys[] = $row['key'];
                }
            }
        } else {
            $modx->log(xPDO::LOG_LEVEL_ERROR, print_r($c->stmt->errorInfo(), 1));
        }
    }

    $rows = [];

    foreach ($keys as $idx => $key) {
        $rows[$idx] = [
            'uid' => $uid,
            'anon' => 1,
            'temp' => 1,
            'share' => 1,
            'createdon' => date('Y-m-d h:i:s'),
            'list' => $list,
            'type' => $type,
            'key' => $key,
            'extra' => [],
            'idx' => $idx + 1,
        ];
    }
    $rows = [$list => $rows];
    $list = array_map('trim', explode(',', $list));
} else {
    $list = is_array($list) ? $list : array_map('trim', explode(',', $list));
    $rows = $modx->runSnippet('msFavorites.objects', array_merge($scriptProperties, ['return' => 'data', 'list' => $list, 'type' => $type, 'groupKey' => 'list']));
}

$pls = [
    'share' => $share,
    'list' => [],
    'total' => [],
];

foreach ($list as $l) {
    $keys = !empty($rows[$l]) ? array_column($rows[$l], 'key') : [];
    $pls['list'][$l] = !empty($keys) ? implode(',', $keys) : '-0';
    $pls['total'][$l] = count($keys);
}
$msFavorites->setPlaceholders($pls);

$log = '';
if ($modx->user->hasSessionContext('mgr') && !empty($showLog)) {
    $log .= '<pre class="msFavoritesLog">' . print_r($pdoFetch->getTime(), 1) . '</pre>';
}
$modx->setPlaceholder('msFavorites.log', $log);

$output = [];
switch ($return) {
    case 'data':
        $output = $pls;
        break;
    case 'json':
        $output = json_encode($pls, true);
        break;
    case 'ids':
    default:
        $output = reset($pls['list']);
        if (!empty($toPlaceholder)) {
            $modx->setPlaceholder($toPlaceholder, $output);
            $output = '';
        }
        break;
}

return $output;

