            'anon' => 1,
            'temp' => 1,
            'share' => 1,
            'createdon' => date('Y-m-d h:i:s'),
            'list' => $list,
            'type' => $type,
            'key' => $key,
            'extra' => [],
            'idx' => $idx + 1,
        ];
    }
    $rows = [$list => $rows];
    $list = array_map('trim', explode(',', $list));
} else {
    $list = is_array($list) ? $list : array_map('trim', explode(',', $list));
