 * @var \SendIt $SendIt
 */

$corePath = $modx->getOption('core_path', '', MODX_CORE_PATH);
require_once $corePath . 'components/ms_cdek2/services/vendor/autoload.php';
$ctx = $modx->context->get('key');
$headers = array_change_key_case(getallheaders());
$action = $headers['x-sipreset'] ?? '';

$result = [];
$output = [
    'message' => '',
    'success' => true,
    'data' => []
];

$Object = new MsCdek2Services\MsCdek2($modx);

switch ($action) {
    case 'mscdek_getsuggestions':
        $output['data'] = $Object->getAddressSuggestions($_POST['query'], $_POST['country']);
        break;
    case 'mscdek_getstatus':
        $Object->addPostalCodeToOrder($_POST);
        $output = $_SESSION['mscdek2'];
        break;
    case 'mscdek_getlist':
        if (empty($_POST['postal_code'])) {
            $output['success'] = false;
            $output['message'] = 'Postal code is empty';
        } else {
            $result = $Object->renderListPVZ($_POST);
            $output['data']['html'] = $result['html'];
            $output['data']['points'] = $result['points'];
            $output['data']['postal_code'] = $_POST['postal_code'];
            $output['data']['coordinates'] = $Object->getCoordinates($_POST['postal_code']);
        }
        break;

    case 'mscdek_getindex':
        $result = $Object->getAddressSuggestions($_POST['city'], $_POST['country']);
        foreach ($result['suggestions'] as $item) {
            if ($item['data']['postal_code']) {
                $output['data']['postal_code'] = $item['data']['postal_code'];
                break;
            }
        }
        break;
    case 'mscdek_update_status':
        $data = $_SESSION['mscdek2']['data'] ?? [];
        foreach ($_POST as $k => $v) {
            if($k === 'fields'){
                continue;
            }
            $decodeValue = json_decode($v, true);
            $_SESSION['mscdek2']['data'][$k] = json_last_error() !== 0 ? $v : $decodeValue;
        }
        break;
}
$output['data']['handler'] = $_REQUEST['handler'];
if ($output['success']) {
    return $SendIt->success($output['message'], $output['data']);
}
return $SendIt->error($output['message'], $output['data']);

